changeSet.sql:
UPDATE claim_request cr SET settlement_no = 'SET-' || grouped.min_id FROM ( SELECT upload_name, MIN(id) AS min_id FROM claim_request WHERE upload_name IS NOT NULL AND BTRIM(upload_name) <> '' GROUP BY upload_name ) grouped WHERE cr.upload_name = grouped.upload_name AND (cr.settlement_no IS NULL OR BTRIM(cr.settlement_no) = '');
UPDATE claim_request SET settlement_no = 'SET-' || id WHERE settlement_no IS NULL OR BTRIM(settlement_no) = '';
UPDATE claim_request SET settlement_no = NULL WHERE status IS DISTINCT FROM 'ACCEPTED' AND settlement_no IS NOT NULL;


DO $$
DECLARE
    max_no BIGINT;
BEGIN
    SELECT MAX(CAST(SUBSTRING(settlement_no FROM 5) AS BIGINT))
    INTO max_no
    FROM claim_request
    WHERE settlement_no ~ '^SET-[0-9]+$';

    IF max_no IS NOT NULL AND max_no > 0 THEN
        PERFORM setval('claim_settlement_seq', max_no);
    END IF;
END $$;
